/*
Codifiche DIWASS dei rifiuti per l'Allegato VII: dati di configurazione, rieseguibile (tabelle create se mancano,
righe allineate con MERGE). Fonte: "DIWASS - lists waste codes - July 2026.xlsx" del pacchetto API v0.5 (CircaBC),
fogli Basel A e B, OECD, WSR Annex IIIA e IIIB. Il nome della lista è quello dell'attributo listID delle API.
L'elenco europeo dei rifiuti (listID low) è la tabella tblRifiutiEer, già in Ecomatico.
tblDiwassCodiciRifiutiEer: codici SUGGERITI per un EER (non è una corrispondenza ufficiale: la classificazione resta
di chi organizza la spedizione), proposti per primi nella scelta del codice. Rivedere con l'utente prima della
produzione. Eseguire con sqlcmd -f 65001 -I sul DB 4_0_ecomatico.
*/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
IF OBJECT_ID('dbo.tblDiwassCodiciRifiuti', 'U') IS NULL
	CREATE TABLE dbo.tblDiwassCodiciRifiuti (
		Lista VARCHAR(10) NOT NULL,
		Codice NVARCHAR(20) NOT NULL,
		Descrizione NVARCHAR(2000) NULL,
		CONSTRAINT PK_tblDiwassCodiciRifiuti PRIMARY KEY CLUSTERED (Lista ASC, Codice ASC)
	);
GO
IF OBJECT_ID('dbo.tblDiwassCodiciRifiutiEer', 'U') IS NULL
	CREATE TABLE dbo.tblDiwassCodiciRifiutiEer (
		IdEer CHAR(6) NOT NULL,
		Lista VARCHAR(10) NOT NULL,
		Codice NVARCHAR(20) NOT NULL,
		Pos TINYINT NULL,
		CONSTRAINT PK_tblDiwassCodiciRifiutiEer PRIMARY KEY CLUSTERED (IdEer ASC, Lista ASC, Codice ASC),
		CONSTRAINT FK_tblDiwassCodiciRifiutiEer_tblRifiutiEer FOREIGN KEY (IdEer) REFERENCES dbo.tblRifiutiEer (Id),
		CONSTRAINT FK_tblDiwassCodiciRifiutiEer_tblDiwassCodiciRifiuti FOREIGN KEY (Lista, Codice) REFERENCES dbo.tblDiwassCodiciRifiuti (Lista, Codice)
	);
GO
